        var cp4 := prompt + generated[..|generated| - |currentConstrainedOut|];
        var t4 := helpers.ConstrainedStep(lm, parser, cp4, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if t4 == eosToken { break; }
        var ng4, ni4, nc4 :=
          helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, t4);
        generated := ng4;
        insideConstrainedOut := ni4;
        currentConstrainedOut := nc4;
      }
    } else {
      var cp4S := prompt + generated[..|generated| - |currentConstrainedOut|];
      var t4S := helpers.ConstrainedStep(lm, parser, cp4S, currentConstrainedOut, eosToken);
      steps := steps + 1;
      if t4S == eosToken { break; }
      var ng4S, ni4S, nc4S :=
        helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, t4S);
      generated := ng4S;
      insideConstrainedOut := ni4S;
      currentConstrainedOut := nc4S;
    }
  }

  // Phase 4b: Safety close after forced-open loop
  if insideConstrainedOut && steps < maxSteps {
    var sb4 := maxSteps - steps;
    if sb4 > 50 { sb4 := 50; }
    if sb4 > 0 {
      var wg4, wi4, wc4 :=
        helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, sb4);
      generated := wg4;
      insideConstrainedOut := wi4;
      currentConstrainedOut := wc4;
      steps := steps + sb4;
      if !insideConstrainedOut { hasCompletedSpan := true; }
    }
  }
}

